public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;

    int sum = 0;
    for (int num : nums) sum += num;

    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == sum / n
    // => sum(subset) * n == sum * k
    // => sum(subset) == sum * k / n
    // So sum * k must be divisible by n.

    // To optimize, we can use the fact that if a subset of size k works,
    // then a subset of size n-k also works (the complement).
    // So we only need to check k from 1 to n/2.

    // Also, we can use a DP approach: dp[k][s] = true if we can pick k elements with sum s.
    // But s can be large. Let's think of bounds.
    // The minimum possible sum for k elements is the sum of the k smallest elements.
    // The maximum possible sum for k elements is the sum of the k largest elements.

    // Alternatively, we can use a bitset or a set of possible sums for each k.
    // Since n is at most 16 (based on typical constraints for this problem), we can use a set.

    // Let's use a set of possible sums for each subset size.
    // dp[k] is a set of sums achievable by picking k elements.

    java.util.Set<Integer>[] dp = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = n; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        long target = (long) sum * k;
        if (target % n != 0) continue;
        int targetSum = (int) (target / n);
        if (dp[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

