    // dp[k] is a set of sums achievable by picking k elements.

    java.util.Set<Integer>[] dp = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = n; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        long target = (long) sum * k;
        if (target % n != 0) continue;
        int targetSum = (int) (target / n);
        if (dp[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

