public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;
    int current = 0;

    for (int i = 0; i < n; i++) {
        current = ((current << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }

    return count == total;
}

