public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The sum of the array is sum_{i=0}^{n-1} (2i+1) = n^2
    // The target value for each element is n^2 / n = n
    // We need to compute the minimum number of operations to make all elements equal to n.
    // Each operation moves 1 unit from one element to another.
    // The minimum number of operations is the sum of the positive differences (or equivalently, the sum of the negative differences in absolute value) between each element and the target.
    // Since the total sum is conserved, the sum of positive differences equals the sum of absolute negative differences.
    // So we can compute: sum over i where arr[i] > n of (arr[i] - n)
    // arr[i] = 2i + 1, target = n
    // We need 2i + 1 > n => i > (n-1)/2
    // Let's compute the sum of (2i + 1 - n) for i from ceil((n-1)/2) to n-1.

    // Alternatively, we can derive a closed form.
    // For n even: n = 2k
    //   target = 2k
    //   arr[i] = 2i+1
    //   We need 2i+1 > 2k => i >= k (since i is integer, 2i+1 > 2k => i > (2k-1)/2 = k - 0.5, so i >= k)
    //   Sum from i=k to i=2k-1 of (2i+1 - 2k)
    //   = sum_{i=k}^{2k-1} (2i + 1 - 2k)
    //   Let j = i - k, then i = j + k, j from 0 to k-1
    //   = sum_{j=0}^{k-1} (2(j+k) + 1 - 2k) = sum_{j=0}^{k-1} (2j + 2k + 1 - 2k) = sum_{j=0}^{k-1} (2j + 1)
    //   = 2 * (0 + 1 + ... + (k-1)) + k = 2 * (k-1)k/2 + k = k(k-1) + k = k^2
    //   So for n=2k, answer = k^2 = (n/2)^2

    // For n odd: n = 2k+1
    //   target = 2k+1
    //   arr[i] = 2i+1
    //   We need 2i+1 > 2k+1 => i > k, so i >= k+1
    //   Sum from i=k+1 to i=2k of (2i+1 - (2k+1)) = sum_{i=k+1}^{2k} (2i - 2k)
    //   Let j = i - (k+1), then i = j + k + 1, j from 0 to k-1
    //   = sum_{j=0}^{k-1} (2(j+k+1) - 2k) = sum_{j=0}^{k-1} (2j + 2k + 2 - 2k) = sum_{j=0}^{k-1} (2j + 2)
    //   = 2 * sum_{j=0}^{k-1} (j+1) = 2 * (1 + 2 + ... + k) = 2 * k(k+1)/2 = k(k+1)
    //   So for n=2k+1, answer = k(k+1) = ((n-1)/2) * ((n+1)/2)

    if (n % 2 == 0) {
        int k = n / 2;
        return k * k;
    } else {
        int k = (n - 1) / 2;
        return k * (k + 1);
    }
}

