                // Anti-diagonal (top-right to bottom-left)
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

                for (int k = 0; k < 4; k++) {
                    max = Math.max(max, dp[i][j][k]);
                }
            }
        }
    }

    return max;
}

