public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquare = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int sqrt = (int) Math.sqrt(sum);
                isSquare[i][j] = (sqrt * sqrt == sum);
            }
        }
    }

    // Use backtracking with memoization
    // State: (usedMask, last)
    // usedMask: bitmask of which elements have been used
    // last: index of the last element placed
    int totalMasks = 1 << n;
    int[][] memo = new int[totalMasks][n];
    for (int[] row : memo) {
        java.util.Arrays.fill(row, -1);
    }

    int result = 0;
    for (int i = 0; i < n; i++) {
        result += backtrack(1 << i, i, n, isSquare, memo);
    }

    return result;
}

